{
  "obligations": [
    {
      "text": "The peewit-export utility must produce CSV files with the exact header order: survey_date, transect_code, species_code, count, easting, northing, recorder_initials, notes. No extra columns allowed.",
      "source_ids": ["m15"]
    },
    {
      "text": "Coordinates must be exported exactly as recorded in the database, with no rounding, snapping, or normalization. The recorder audits against the raw field logs.",
      "source_ids": ["m07"]
    },
    {
      "text": "Dates must be in ISO 8601 format (YYYY-MM-DD) throughout the output. Locale-based date formats are prohibited.",
      "source_ids": ["m05"]
    },
    {
      "text": "Filenames must follow the format tbo_<transect-slug>_<survey-date>.csv, all in lowercase, with one file per transect per survey date.",
      "source_ids": ["m08"]
    },
    {
      "text": "Records with verification_status 'pending' or 'rejected' must be excluded from exports unless the --include-unverified flag is used.",
      "source_ids": ["m09"]
    },
    {
      "text": "Sensitive species (Little Tern, Dartford Warbler, Nightjar) must have their coordinates replaced with the centroid of their 2km grid square in the public profile. The internal profile keeps exact coordinates.",
      "source_ids": ["m10"]
    },
    {
      "text": "Nightjar records are embargoed until 31 August 2026 and must be excluded from all exports until then, overriding the normal blur-in-public handling.",
      "source_ids": ["m18"]
    },
    {
      "text": "Zero-count rows must be included in exports. Counts must be exported verbatim, and no smoothing or filtering based on count values is allowed.",
      "source_ids": ["m21"]
    },
    {
      "text": "GeoJSON output must follow RFC 7946, use WGS84, and include coordinates in longitude-latitude order. Coordinates must be converted to lon/lat at full precision without rounding.",
      "source_ids": ["m24"]
    },
    {
      "text": "The 'blurred' property in GeoJSON must be a boolean, set to true only when the centroid substitution was applied for sensitive species in the public profile.",
      "source_ids": ["m27"]
    },
    {
      "text": "The --summary flag must print per-transect totals (rows written, sensitive records blurred, embargoed rows withheld) after a run, if it does not delay the GeoJSON work.",
      "source_ids": ["m29"]
    },
    {
      "text": "The weekly batch runner must process all active transects for a given ISO week, producing both CSV and GeoJSON files per transect under all existing conventions. Transects with no eligible records must be skipped and logged.",
      "source_ids": ["m40"]
    },
    {
      "text": "stdout must carry only the paths of files actually written. Any skips, withholdings, or errors must be logged to stderr.",
      "source_ids": ["m39"]
    }
  ]
}
